297. int 
298. png_icc_check_header(png_const_structrp png_ptr, png_colorspacerp colorspace,
299.     png_const_charp name, png_uint_32 profile_length,
300.     png_const_bytep profile, int color_type)
301. {
302.    png_uint_32 temp;
303. 
304.    temp = png_get_uint_32(profile);
305.    if (temp != profile_length)
306.       return png_icc_profile_error(png_ptr, colorspace, name, temp,
307.           "length does not match profile");
308. 
309.    temp = (png_uint_32) (*(profile+8));
310.    if (temp > 3 && (profile_length & 3))
311.       return png_icc_profile_error(png_ptr, colorspace, name, profile_length,
312.           "invalid length");
313. 
314.    temp = png_get_uint_32(profile+128); 
315.    if (temp > 357913930 || 
316.       profile_length < 132+12*temp) 
317.       return png_icc_profile_error(png_ptr, colorspace, name, temp,
318.           "tag count too large");
319. 
320.    temp = png_get_uint_32(profile+64);
321.    if (temp >= 0xffff) 
322.       return png_icc_profile_error(png_ptr, colorspace, name, temp,
323.           "invalid rendering intent");
324. 
325.    if (temp >= PNG_sRGB_INTENT_LAST)
326.       (void)png_icc_profile_error(png_ptr, NULL, name, temp,
327.           "intent outside defined range");
328. 
329.    temp = png_get_uint_32(profile+36); 
330.    if (temp != 0x61637370)
331.       return png_icc_profile_error(png_ptr, colorspace, name, temp,
332.           "invalid signature");
333. 
334.    if (memcmp(profile+68, D50_nCIEXYZ, 12) != 0)
335.       (void)png_icc_profile_error(png_ptr, NULL, name, 0,
336.           "PCS illuminant is not D50");
337. 
338.    temp = png_get_uint_32(profile+16); 
339.    switch (temp)
340.    {
341.       case 0x52474220: 
342.          if ((color_type & PNG_COLOR_MASK_COLOR) == 0)
343.             return png_icc_profile_error(png_ptr, colorspace, name, temp,
344.                 "RGB color space not permitted on grayscale PNG");
345.          break;
346. 
347.       case 0x47524159: 
348.          if ((color_type & PNG_COLOR_MASK_COLOR) != 0)
349.             return png_icc_profile_error(png_ptr, colorspace, name, temp,
350.                 "Gray color space not permitted on RGB PNG");
351.          break;
352. 
353.       default:
354.          return png_icc_profile_error(png_ptr, colorspace, name, temp,
355.              "invalid ICC profile color space");
356.    }
357. 
358.    temp = png_get_uint_32(profile+12); 
359.    switch (temp)
360.    {
361.       case 0x73636e72: 
362.       case 0x6d6e7472: 
363.       case 0x70727472: 
364.       case 0x73706163: 
365.          
366.          break;
367. 
368.       case 0x61627374: 
369.          
370.          return png_icc_profile_error(png_ptr, colorspace, name, temp,
371.              "invalid embedded Abstract ICC profile");
372. 
373.       case 0x6c696e6b: 
374.          
375.          return png_icc_profile_error(png_ptr, colorspace, name, temp,
376.              "unexpected DeviceLink ICC profile class");
377. 
378.       case 0x6e6d636c: 
379.          
380.          (void)png_icc_profile_error(png_ptr, NULL, name, temp,
381.              "unexpected NamedColor ICC profile class");
382.          break;
383. 
384.       default:
385.          
386.          (void)png_icc_profile_error(png_ptr, NULL, name, temp,
387.              "unrecognized ICC profile class");
388.          break;
389.    }
390. 
391.    temp = png_get_uint_32(profile+20);
392.    switch (temp)
393.    {
394.       case 0x58595a20: 
395.       case 0x4c616220: 
396.          break;
397. 
398.       default:
399.          return png_icc_profile_error(png_ptr, colorspace, name, temp,
400.              "unexpected ICC PCS encoding");
401.    }
402. 
403.    return 1;
404. }
