406. int 
407. png_icc_check_tag_table(png_const_structrp png_ptr, png_colorspacerp colorspace,
408.     png_const_charp name, png_uint_32 profile_length,
409.     png_const_bytep profile )
410. {
411.    png_uint_32 tag_count = png_get_uint_32(profile+128);
412.    png_uint_32 itag;
413.    png_const_bytep tag = profile+132; 
414. 
415.    for (itag=0; itag < tag_count; ++itag, tag += 12)
416.    {
417.       png_uint_32 tag_id = png_get_uint_32(tag+0);
418.       png_uint_32 tag_start = png_get_uint_32(tag+4); 
419.       png_uint_32 tag_length = png_get_uint_32(tag+8);
420. 
421.       if (tag_start > profile_length || tag_length > profile_length - tag_start)
422.          return png_icc_profile_error(png_ptr, colorspace, name, tag_id,
423.              "ICC profile tag outside profile");
424. 
425.       if ((tag_start & 3) != 0)
426.       {
427.          
428.          (void)png_icc_profile_error(png_ptr, NULL, name, tag_id,
429.              "ICC profile tag start not a multiple of 4");
430.       }
431.    }
432. 
433.    return 1; 
434. }
