+            Iterator<Attribute> jsoupAttrs = node.attributes().iterator();
+            while (jsoupAttrs.hasNext()) {
+                Attribute jsoupAttr = jsoupAttrs.next();
+                attributes.addAttribute("", jsoupAttr.getKey(), jsoupAttr.getKey(), "",
+                        jsoupAttr.getValue());
+            }
+            try {
